    for(auto [name,items]:std::initializer_list<std::pair<const char*,bool>>{{"SetAllItemTypeSlots",true},{"SetAllUnitTypeSlots",false}})bind(name,"nothing",{"integer"},[this,items](auto& vm,auto args){auto count=std::bit_cast<std::int32_t>(args[0].bits);if(count<0 || count>1024)throw std::runtime_error("Invalid stock slot count");(items?stockItemSlots_:stockUnitSlots_)=count;return vm.nothing();});
